 function alignmentReason(clip,side){const a=clip?.[side]?.alignment;if(!a?.model)return '';const p=a.model.provenance;if(!p?.source||!p.reference)return '此對位缺少來源資訊，請重新計算。';const cached=alignmentInvalid.get(alignmentKey(a));if(cached)return cached;if(p.scope!=='transition'||p.source.job_id!==clip.job_id||p.source.version!==clip.version||p.source.clip_key!==clip.key||p.source.side!==side||p.source.frame!==(side==='head'?clip.start:clip.end))return '修整端的來源或首尾幀已變更，請重新對齊。';const ref=project?.clips.find(c=>c.key===p.reference.clip_key);if(!ref||ref.job_id!==p.reference.job_id||ref.version!==p.reference.version||p.reference.frame!==(p.reference.side==='head'?ref.start:ref.end))return '計算時參考的來源或端點已變更，請重新對齊。';return ''}
